mapper.select:
SELECT t.*,
       (t3.model_shop_id = #{query.modeShopId}) AS inUse,
        t4.model_shop_name,
       t3.name as storeName
FROM model_shop_use_record t
INNER JOIN (
    SELECT store_id, MAX(id) as max_id
    FROM model_shop_use_record
    WHERE model_shop_id = #{query.modeShopId}

        AND store_id = #{query.storeId}


    AND store_id IN

        #{item}


    GROUP BY store_id
) t2 ON t.store_id = t2.store_id AND t.id = t2.max_id
LEFT JOIN store t3 ON t3.id = t.store_id
LEFT JOIN model_shop t4 ON t4.id = t.model_shop_id
WHERE t.model_shop_id = #{query.modeShopId}

    AND t3.name LIKE CONCAT('%', #{query.storeName}, '%')


    AND t.create_time BETWEEN #{query.useTimeL} AND #{query.useTimeR}


    AND t3.model_shop_id = #{query.modeShopId}


    AND (t3.model_shop_id IS NULL OR t3.model_shop_id != #{query.modeShopId})

ORDER BY t.id DESC
